const items = $input.all();

function detectType(buffer) {
  const hex4 = buffer.slice(0, 4).toString('hex').toUpperCase();
  const hex2 = buffer.slice(0, 2).toString('hex').toUpperCase();

  if (hex4.startsWith('504B0304')) return 'zip';
  if (hex2.startsWith('1F8B')) return 'gzip';
  if (hex4.startsWith('7B') || hex4.startsWith('5B')) return 'json-like';
  return 'unknown';
}

const files = [];

for (const item of items) {
  if (!item.binary) continue;

  for (const [key, file] of Object.entries(item.binary)) {
    const buffer = Buffer.from(file.data, 'base64');
    const utf8Preview = buffer.toString('utf8', 0, 200);
    const hexPreview = buffer.slice(0, 32).toString('hex').toUpperCase();

    files.push({
      field_name: key,
      file_name: file.fileName || null,
      mime_type: file.mimeType || null,
      file_size: file.fileSize || null,
      detected_type: detectType(buffer),
      hex_preview: hexPreview,
      utf8_preview: utf8Preview,
    });
  }
}

return [{ json: { files } }];

const items = $input.all();

let parsedJson = null;
const images = [];
const debug = [];

for (let itemIndex = 0; itemIndex < items.length; itemIndex++) {
  const item = items[itemIndex];

  if (!item.binary) continue;

  for (const [key, file] of Object.entries(item.binary)) {
    const fileName = file.fileName || '';
    const mimeType = file.mimeType || '';

    const isJsonFile =
      mimeType === 'application/json' ||
      fileName.toLowerCase().endsWith('.json') ||
      fileName.toLowerCase() === 'manifest.json';

    if (isJsonFile && parsedJson === null) {
      try {
        const buffer = await this.helpers.getBinaryDataBuffer(itemIndex, key);
        const text = buffer.toString('utf8').trim();
        parsedJson = JSON.parse(text);

        debug.push({
          parsed_from: key,
          file_name: fileName,
          mime_type: mimeType,
        });
      } catch (error) {
        throw new Error(
          `Ошибка парсинга JSON из ${key} (${fileName}): ${error.message}`
        );
      }
    } else {
      images.push({
        field_name: key,
        file_name: fileName,
        mime_type: mimeType,
        file_size: file.fileSize || null,
      });
    }
  }
}

if (!parsedJson) {
  throw new Error('JSON-файл не найден среди binary-вложений');
}

return [
  {
    json: {
      manifest: parsedJson,
      images_count: images.length,
      images,
      debug,
    },
  },
];

