const isSignal =
  typeof parsed.is_signal === 'boolean'
    ? parsed.is_signal
    : postType === 'signal';

const reason =
  typeof parsed.reason === 'string' && parsed.reason.trim()
    ? parsed.reason.trim()
    : 'No reason provided';

const messageId =
  parsed.message_id ?? src.message_id ?? null;

// Дополнительная логическая коррекция:
