const finalDirection = postType === 'signal' ? direction : null;
const finalIsSignal = postType === 'signal' && isSignal ? true : false;

const validationWarnings = [];

if (parsed.post_type !== postType) {
  validationWarnings.push(`post_type normalized: ${parsed.post_type} -> ${postType}`);
}
if (parsed.direction !== finalDirection) {
  validationWarnings.push(`direction normalized: ${parsed.direction} -> ${finalDirection}`);
}
if (parsed.ticker !== finalTicker) {
  validationWarnings.push(`ticker normalized: ${parsed.ticker} -> ${finalTicker}`);
}
if (parsed.confidence !== confidence) {
  validationWarnings.push(`confidence normalized: ${parsed.confidence} -> ${confidence}`);
}

return {
  json: {
    ...src,
